function seed() {
  const exercises = SEED_EX.map(([name, ru, group, kind]) => ({ id: slug(name), name, ru, group, kind: kind || "reps" }));
  const P = (name, ids) => ({ id: uid(), name, items: ids.map((exerciseId) => ({ exerciseId, sets: 3 })) });
  return {
    version: 2,
    exercises,
    programs: [
      P("I. Ноги и плечи", ["squat", "leg-extension", "leg-curl", "lateral-raise", "overhead-press", "deadlift", "calf-raise"]),
      P("II. Грудь и спина", ["dumbbell-bench-press", "seated-row", "dips", "pullover", "cable-preacher-curl", "cable-extension", "wrist-curl"]),
      P("III. Ноги и плечи", ["belt-squat", "bulgarian-split-squat", "hip-thrust", "upright-row", "reverse-fly", "deadlift", "calf-raise"]),
      P("IV. Грудь и спина", ["barbell-bench-press", "lat-pulldown", "cable-crossover", "machine-row", "dumbbell-seated-curl", "cable-extension-samurai", "wrist-curl"]),
    ],
    workouts: [],
    measurements: [],
    active: null,
    settings: { restSec: 120 },
  };
}


// adds new built-in exercises and Russian names to data saved by older versions
function migrate(d) {
  const base = seed();
  const byId = Object.fromEntries(d.exercises.map((e) => [e.id, e]));
  base.exercises.forEach((se) => {
    const e = byId[se.id];
    if (!e) d.exercises.push(se);
    else if (!e.ru) e.ru = se.ru;
  });
  if (!Array.isArray(d.measurements)) d.measurements = [];
  d.exercises.forEach((e) => {
    if (e.bw === undefined && BW_DEFAULTS[e.id]) e.bw = BW_DEFAULTS[e.id];
    if (e.assist === undefined && ASSIST_DEFAULTS[e.id]) e.assist = true;
  });
  // flatten nested drop sets from an earlier version into linear grouped sets
  const flat = (sets) => {
    const out = [];
    sets.forEach((st) => {
      if (st.drops && st.drops.length) {
        const g = uid();
        const { drops, ...base } = st;
        out.push({ ...base, g });
        drops.forEach((dr) => out.push({ w: dr.w, r: dr.r, p: "", done: base.done, g, ...(dr.hw != null ? { hw: dr.hw, hr: dr.hr } : {}) }));
      } else {
        if (st.drops) delete st.drops;
        out.push(st);
      }
    });
    return out;
  };
  d.workouts.forEach((w) => w.exercises.forEach((e) => { e.sets = flat(e.sets); }));
  if (d.active) d.active.exercises.forEach((e) => { e.sets = flat(e.sets); });
  d.version = 3;
  return d;
}

// ---------- helpers ----------
function lastSession(workouts, exId) {
  for (let i = workouts.length - 1; i >= 0; i--) {
    const e = workouts[i].exercises.find((x) => x.exerciseId === exId);
    if (e && e.sets.length) return { workout: workouts[i], sets: e.sets };
  }
  return null;
}

function buildSets(d, exId, n) {
  const last = lastSession(d.workouts, exId);
  const prev = last ? last.sets : [];
  const count = n || Math.max(prev.length, 3);
  return Array.from({ length: count }, (_, i) => {
    const s = prev[i] || prev[prev.length - 1];
    // values from last time are hints (shown gray), not entered values
    return {
      w: "", r: "", p: "", t: s && s.t === "w" ? "w" : "",
      ...(prev[i] && prev[i].g ? { g: prev[i].g } : {}), hw: s ? s.w : "", hr: s ? s.r : "", hp: s && s.p ? s.p : "", done: false };
  });
}

// A workout can be paused and continued later the same day (gym, then sets at home).
// Each continuation is a segment; the longest one is the "main" session.
function segmentsOf(w) {
  return w.segments && w.segments.length ? w.segments : [{ start: w.startedAt, end: w.finishedAt }];
}
function durations(w, now = Date.now()) {
  const segs = segmentsOf(w).map((s) => Math.max(0, (s.end || now) - s.start));
  const main = Math.max(0, ...segs);
  const total = segs.reduce((x, y) => x + y, 0);
  return { main, extra: total - main, count: segs.length };
}
const fmtWDur = (st) => fmtDur(st.dur) + (st.extra >= 60000 ? ` +${fmtDur(st.extra)}` : "");

function closeSegment(w, t = Date.now()) {
  w.segments = segmentsOf(w).map((s) => ({ ...s }));
  const last = w.segments[w.segments.length - 1];
  if (!last.end) last.end = t;
}

function finalizeActive(d, updateProgram) {
  const w = d.active;
  if (!w) return null;
  if (updateProgram) {
    const p = d.programs.find((x) => x.id === w.programId);
    if (p) p.items = w.exercises.map((e) => ({ exerciseId: e.exerciseId, sets: e.sets.length || 1 }));
  }
  closeSegment(w);
  w.finishedAt = w.segments[w.segments.length - 1].end;
  delete w.restEndsAt;
  delete w.paused;
  w.exercises = w.exercises
    .map((e) => ({ ...e, sets: e.sets.filter((s) => s.done).map(({ w: sw, r, p, t, rir, g, at, done }) => ({
      w: sw, r, p: p || "", ...(t ? { t } : {}), ...(rir != null ? { rir } : {}), ...(g ? { g } : {}), ...(at ? { at } : {}), done,
    })) }))
    .filter((e) => e.sets.length);
  if (w.exercises.length) d.workouts.push(w);
  d.active = null;
  return w.id;
}

const PARTIAL_WEIGHT = 0.3;

// ---------- rest times ----------
// Gaps between consecutive confirmed sets. Steps of a drop set don't count, nor gaps across a pause
// or longer than 15 min (that's not rest, that's a break).
function restStats(w) {
  const evs = [];
  w.exercises.forEach((e, ei) => e.sets.forEach((s) => { if (s.done && s.at) evs.push({ at: s.at, ei, g: s.g }); }));
  evs.sort((a, b) => a.at - b.at);
  const pauses = segmentsOf(w).map((sg) => sg.end).filter(Boolean);
  const between = { sets: [], ex: [] };
  for (let i = 1; i < evs.length; i++) {
    const a = evs[i - 1], b = evs[i];
    const gap = b.at - a.at;
    if (gap <= 0 || gap > 15 * 60e3) continue;
    if (pauses.some((t) => t > a.at && t < b.at)) continue;
    if (a.ei === b.ei && a.g && a.g === b.g) continue;
    (a.ei === b.ei ? between.sets : between.ex).push(gap);
  }
  const avg = (xs) => (xs.length ? xs.reduce((x, y) => x + y, 0) / xs.length : 0);
  return { sets: avg(between.sets), ex: avg(between.ex), nSets: between.sets.length, nEx: between.ex.length };
}

// ---------- bodyweight exercises ----------
// For exercises where the body is the main load, working load = share of body weight + added weight.
// Shares are rough biomechanics figures. "assist" = machine-assisted (gravitron): load = body weight − assistance.
const BW_DEFAULTS = {
  "pull-up": 1, "close-grip-chin-up": 1, "dips": 0.95, "triceps-dips": 0.95,
  "bodyweight-squat": 0.85, "push-up": 0.65, "one-arm-push-up": 0.65, "inverted-row": 0.55,
};
const ASSIST_DEFAULTS = { "assisted-pull-up": true };
// body weight source, refreshed by App on every render (measurements + settings fallback)
let bodyCtx = { measurements: [], fallback: 0 };
function bodyWeightAt(ts) {
  const dayEnd = new Date(ts).setHours(23, 59, 59, 999);
  let best = null;
  for (const m of bodyCtx.measurements) {
    const v = num(m.values && m.values.weight);
    if (!v) continue;
    if (m.date <= dayEnd && (!best || m.date > best.date)) best = m;
  }
  if (!best) { // nothing before that day: take the earliest measurement after it
    for (const m of bodyCtx.measurements) {
      const v = num(m.values && m.values.weight);
      if (v && (!best || m.date < best.date)) best = m;
    }
  }
  return best ? num(best.values.weight) : num(bodyCtx.fallback);
}
function setLoad(ex, s, bw) {
  if (ex && ex.assist) return Math.max(0, bw - num(s.w));
  if (ex && ex.bw) return ex.bw * bw + num(s.w);
  return num(s.w);
}

function stats(w, exMap) {
  let vol = 0, sets = 0;
  const bw = bodyWeightAt(w.startedAt);
  w.exercises.forEach((e) => {
    const exd = exMap[e.exerciseId];
    const kind = exd?.kind;
    e.sets.forEach((s, i) => {
      if (!s.done || s.t === "w") return; // warm-ups don't count
      const cont = s.g && i > 0 && e.sets[i - 1].g === s.g && e.sets[i - 1].done;
      if (!cont) sets++; // a drop set / ladder is one set
      // partial reps count as 30% of a full rep
      if (kind !== "time") vol += setLoad(exd, s, bw) * (num(s.r) + PARTIAL_WEIGHT * num(s.p));
      if (kind !== "time") (s.drops || []).forEach((dr) => { vol += num(dr.w) * num(dr.r); });
    });
  });
  const { main, extra, count } = durations(w);
  return { vol, sets, dur: main, extra, segments: count };
}

const pad = (n) => String(n).padStart(2, "0");
function fmtDur(ms) {
  const t = Math.max(0, Math.floor(ms / 1000));
  const h = Math.floor(t / 3600), m = Math.floor((t % 3600) / 60), s = t % 60;
  return h ? `${h}:${pad(m)}:${pad(s)}` : `${m}:${pad(s)}`;
}
const fmtKg = (v) => (v >= 1000 ? `${(v / 1000).toFixed(1).replace(".", ",")} т` : `${Math.round(v)} кг`);
const fmtDate = (ts) => new Date(ts).toLocaleDateString("ru-RU", { weekday: "short", day: "numeric", month: "short" });
const fmtShort = (ts) => new Date(ts).toLocaleDateString("ru-RU", { day: "numeric", month: "numeric" });
// Effort per set, RP / Israetel style: reps in reserve. 4 means "4 or more".
const RIR = [[4, "4+", "легко"], [3, "3", "норм"], [2, "2", "норм"], [1, "1", "тяжело"], [0, "0", "отказ"]];
const rirLabel = (s) => (s.t === "w" ? "разм." : s.rir === 0 ? "отказ" : s.rir != null ? `RIR ${s.rir === 4 ? "4+" : s.rir}` : "");

// Set row columns: order and visibility are user settings. Weight and reps can't be hidden.
const COLUMNS = { w: "Вес", r: "Повторы / секунды", p: "Частичные повторы", rir: "RIR (повторов в запасе)" };
const DEFAULT_COLUMNS = [{ key: "w", on: true }, { key: "r", on: true }, { key: "p", on: true }, { key: "rir", on: true }];
function columnConfig(settings) {
  const saved = (settings && settings.columns) || [];
  const known = saved.filter((c) => COLUMNS[c.key]);
  DEFAULT_COLUMNS.forEach((c) => { if (!known.some((k) => k.key === c.key)) known.push({ ...c }); });
  return known;
}
const setColumns = (settings) => columnConfig(settings).filter((c) => c.on || c.key === "w" || c.key === "r").map((c) => c.key);

// Sets merged into one (drop set, ladder) share a group id `g` and sit next to each other.
function setLabels(sets) {
  let n = 0, sub = 0;
  return sets.map((s, i) => {
    const cont = s.g && i > 0 && sets[i - 1].g === s.g;
    if (cont) sub++; else { n++; sub = 0; }
    const grouped = s.g && (cont || (i < sets.length - 1 && sets[i + 1].g === s.g));
    return grouped ? `${n}${"abcdefghij"[sub] || "+"}` : String(n);
  });
}
function normalizeGroups(sets) {
  const cnt = {};
  sets.forEach((s) => { if (s.g) cnt[s.g] = (cnt[s.g] || 0) + 1; });
  sets.forEach((s) => { if (s.g && cnt[s.g] < 2) delete s.g; });
}

function fmtSets(sets, kind) {
  const parts = sets
    .map((s) => {
      let base = kind === "time" ? `${num(s.w) ? num(s.w) + " кг × " : ""}${num(s.r)} с` : `${num(s.w)}×${num(s.r)}${num(s.p) ? `+${num(s.p)}` : ""}`;
      (s.drops || []).forEach((dr) => { base += ` → ${num(dr.w)}×${num(dr.r)}`; });
      if (s.t === "w") return `разм. ${base}`;
      return s.rir === 0 ? `${base} отказ` : s.rir != null ? `${base} RIR${s.rir === 4 ? "4+" : s.rir}` : base;
    });
  return parts.map((p, i) => (i === 0 ? "" : sets[i].g && sets[i - 1].g === sets[i].g ? " → " : ", ") + p).join("");
}

function useNow(ms, on = true) {
  const [n, setN] = useState(Date.now());
  useEffect(() => {
    if (!on) return;
    const t = setInterval(() => setN(Date.now()), ms);
    return () => clearInterval(t);
  }, [ms, on]);
  return n;
}


