// ---------- sound ----------
let actx = null;
function unlockAudio() {
  try {
    // iOS: "ambient" mixes with music instead of stopping it (but respects the silent switch)
    if (navigator.audioSession) navigator.audioSession.type = "ambient";
    if (!actx) { const C = window.AudioContext || window.webkitAudioContext; actx = new C(); }
    if (actx.state === "suspended") actx.resume();
  } catch (e) {}
}
function tone(freq, at, len, vol = 0.35) {
  const o = actx.createOscillator(), g = actx.createGain();
  o.frequency.value = freq;
  o.connect(g); g.connect(actx.destination);
  const s = actx.currentTime + at;
  g.gain.setValueAtTime(0.0001, s);
  g.gain.exponentialRampToValueAtTime(vol, s + 0.015);
  g.gain.exponentialRampToValueAtTime(0.0001, s + len);
  o.start(s); o.stop(s + len + 0.05);
}
// short tick for the 3-2-1 countdown
function tick() {
  if (!actx) return;
  try { if (actx.state === "suspended") actx.resume(); tone(660, 0, 0.09, 0.3); } catch (e) {}
}
// soft blip when rest starts
function blip() {
  if (!actx) return;
  try { if (actx.state === "suspended") actx.resume(); tone(520, 0, 0.07, 0.15); } catch (e) {}
}
function beep() {
  if (!actx) return;
  try { if (actx.state === "suspended") actx.resume(); tone(988, 0, 0.18); tone(988, 0.22, 0.18); tone(1319, 0.44, 0.45); } catch (e) {}
}
function beepOld() {
  if (!actx) return;
  try {
    [0, 0.35, 0.7].forEach((t) => {
      const o = actx.createOscillator(), g = actx.createGain();
      o.frequency.value = 880;
      o.connect(g); g.connect(actx.destination);
      const s = actx.currentTime + t;
      g.gain.setValueAtTime(0.0001, s);
      g.gain.exponentialRampToValueAtTime(0.35, s + 0.02);
      g.gain.exponentialRampToValueAtTime(0.0001, s + 0.25);
      o.start(s); o.stop(s + 0.3);
    });
  } catch (e) {}
}

// ---------- small UI ----------
function ConfirmButton({ onConfirm, children, className = "", armedClassName = "", confirmText = "Точно?" }) {
  const [armed, setArmed] = useState(false);
  useEffect(() => {
    if (!armed) return;
    const t = setTimeout(() => setArmed(false), 3000);
    return () => clearTimeout(t);
  }, [armed]);
  return (
    <button
      className={armed ? armedClassName : className}
      onClick={() => (armed ? (setArmed(false), onConfirm()) : setArmed(true))}
    >
      {armed ? confirmText : children}
    </button>
  );
}

function Header({ title, back, right }) {
  return (
    <div className="flex items-center gap-2 mb-4">
      {back && (
        <button onClick={back} className="-ml-2 shrink-0 p-2 text-neutral-400" aria-label="Назад">
          <ChevronLeft size={24} />
        </button>
      )}
      <h1 className="min-w-0 flex-1 text-xl font-bold leading-tight tracking-tight">{title}</h1>
      {right}
    </div>
  );
}

function Stepper({ value, onChange, step = 1, min = 1, fmt = (v) => v, compact }) {
  const btn = compact ? "p-1.5 text-neutral-300" : "p-2 text-neutral-300";
  return (
    <div className="flex items-center rounded-lg bg-neutral-800">
      <button className={btn} onClick={() => onChange(Math.max(min, value - step))}><Minus size={compact ? 14 : 16} /></button>
      <span className={`${compact ? "w-6" : "w-12"} text-center tabular-nums`}>{fmt(value)}</span>
      <button className={btn} onClick={() => onChange(value + step)}><Plus size={compact ? 14 : 16} /></button>
    </div>
  );
}

// ---------- exercise list (used in tab and picker) ----------
function ExerciseList({ data, up, onSelect, autoFocus }) {
  const [q, setQ] = useState("");
  const [filter, setFilter] = useState(""); // muscle group, "" = all
  const [creating, setCreating] = useState(false);
  const [newName, setNewName] = useState("");
  const [newRu, setNewRu] = useState("");
  const [grp, setGrp] = useState("спина");
  const [kind, setKind] = useState("reps");
  const ql = q.trim().toLowerCase();
  const words = ql.split(/\s+/).filter(Boolean);
  const allGroups = [...GROUPS, ...new Set(data.exercises.map((e) => e.group).filter((g) => !GROUPS.includes(g)))];
  // every typed word must appear in the English or Russian name: "dumb curl", "тяга одной"
  const filtered = data.exercises.filter((e) => {
    if (filter && e.group !== filter) return false;
    const hay = `${e.name} ${e.ru || ""}`.toLowerCase();
    return words.every((w) => hay.includes(w));
  });
  // "yours" first: exercises you've done (most often first) or have in a program
  const usage = useMemo(() => {
    const u = {};
    data.workouts.forEach((w) => w.exercises.forEach((e) => {
      const x = u[e.exerciseId] || (u[e.exerciseId] = { n: 0, last: 0 });
      x.n += 1; x.last = Math.max(x.last, w.startedAt);
    }));
    data.programs.forEach((p) => p.items.forEach((it) => { if (!u[it.exerciseId]) u[it.exerciseId] = { n: 0.5, last: 0 }; }));
    return u;
  }, [data.workouts, data.programs]);
  const mine = filtered.filter((e) => usage[e.id])
    .sort((x, y) => usage[y.id].n - usage[x.id].n || usage[y.id].last - usage[x.id].last || x.name.localeCompare(y.name));
  const rest = filtered.filter((e) => !usage[e.id]);
  const byGroup = [
    ...(mine.length ? [["твои", mine]] : []),
    ...allGroups.map((g) => [g, rest.filter((e) => e.group === g).sort((x, y) => x.name.localeCompare(y.name))]).filter(([, l]) => l.length),
  ];
  const exact = data.exercises.some((e) => e.name.toLowerCase() === ql || (e.ru || "").toLowerCase() === ql);

  const chip = (active) => `shrink-0 rounded-full px-3 py-1 text-xs ${active ? "bg-amber-400 text-black" : "bg-neutral-800 text-neutral-300"}`;
  const startCreate = (name) => { setNewName(name); setNewRu(""); if (filter) setGrp(filter); setCreating(true); };
  const create = () => {
    const name = newName.trim();
    if (!name) return;
    const ex = { id: uid(), name, ...(newRu.trim() ? { ru: newRu.trim() } : {}), group: grp, kind };
    up((d) => { d.exercises.push(ex); });
    setQ(""); setCreating(false);
    onSelect(ex);
  };
  const createForm = (
    <div className="mt-3 rounded-xl border border-dashed border-neutral-700 p-3">
      <input value={newName} onChange={(e) => setNewName(e.target.value)} placeholder="Название"
        className="mb-2 w-full rounded-lg bg-black px-3 py-2.5 outline-none placeholder-neutral-600 focus:ring-2 focus:ring-amber-400" />
      <input value={newRu} onChange={(e) => setNewRu(e.target.value)} placeholder="Второе название (необязательно)"
        className="mb-3 w-full rounded-lg bg-black px-3 py-2.5 outline-none placeholder-neutral-600 focus:ring-2 focus:ring-amber-400" />
      <div className="mb-2 text-xs text-neutral-400">Группа мышц</div>
      <div className="mb-3 flex flex-wrap gap-1.5">
        {GROUPS.map((g) => <button key={g} onClick={() => setGrp(g)} className={chip(grp === g)}>{g}</button>)}
      </div>
      <div className="mb-3 flex gap-1.5">
        {[["reps", "вес и повторы"], ["time", "вес и время"]].map(([k, l]) => (
          <button key={k} onClick={() => setKind(k)}
            className={`rounded-full px-3 py-1 text-xs ${kind === k ? "bg-neutral-100 text-black" : "bg-neutral-800 text-neutral-300"}`}>{l}</button>
        ))}
      </div>
      <div className="flex gap-2">
        <button onClick={() => setCreating(false)} className="rounded-lg bg-neutral-800 px-4 py-2.5 text-neutral-300">Отмена</button>
        <button onClick={create} disabled={!newName.trim()} className="flex-1 rounded-lg bg-amber-400 py-2.5 font-semibold text-black disabled:opacity-40">Создать</button>
      </div>
    </div>
  );

  return (
    <div>
      <div className="flex items-center gap-2 rounded-xl bg-neutral-900 px-3">
        <Search size={18} className="text-neutral-500" />
        <input autoFocus={autoFocus} value={q} onChange={(e) => { setQ(e.target.value); setCreating(false); }}
          placeholder="Поиск по-русски или по-английски"
          className="flex-1 bg-transparent py-3 outline-none placeholder-neutral-500" />
        {q && <button onClick={() => setQ("")} className="text-neutral-500"><X size={18} /></button>}
      </div>

      {creating ? createForm : (
        <button onClick={() => startCreate(q.trim())} className="mt-2 w-full rounded-xl border border-dashed border-neutral-700 py-2.5 text-sm text-neutral-300">
          + Новое упражнение
        </button>
      )}

      <div className="-mx-4 mt-2 flex gap-1.5 overflow-x-auto px-4 pb-1">
        <button onClick={() => setFilter("")} className={chip(!filter)}>все</button>
        {allGroups.map((g) => (
          <button key={g} onClick={() => setFilter(filter === g ? "" : g)} className={chip(filter === g)}>{g}</button>
        ))}
      </div>

      {byGroup.length === 0 && <p className="mt-4 text-neutral-400">Ничего не нашлось.</p>}

      {byGroup.map(([g, list]) => (
        <div key={g} className="mt-4">
          <div className={`mb-1 px-1 text-xs ${g === "твои" ? "font-semibold text-amber-400" : "text-neutral-500"}`}>
            {g === "твои" ? "Твои упражнения" : g}
          </div>
          <div className="divide-y divide-neutral-800 rounded-xl bg-neutral-900">
            {list.map((e) => (
              <button key={e.id} onClick={() => onSelect(e)} className="flex w-full items-center gap-3 px-3 py-2 text-left active:bg-neutral-800">
                <ExImg ex={e} />
                <span className="min-w-0 flex-1">
                  <span className="block">{e.name}</span>
                  {e.ru && <span className="block text-xs text-neutral-500">{e.ru}</span>}
                </span>
                {g === "твои" && <span className="ml-2 text-[11px] text-neutral-500">{e.group}</span>}
                {e.kind === "time" && <span className="ml-2 text-xs text-neutral-500">на время</span>}
              </button>
            ))}
          </div>
        </div>
      ))}

      {ql && !exact && !creating && (
        <button onClick={() => { startCreate(q.trim()); window.scrollTo({ top: 0, behavior: "smooth" }); }}
          className="mt-4 w-full rounded-xl border border-dashed border-neutral-700 py-3 text-neutral-300">
          + Создать «{q.trim()}»
        </button>
      )}
    </div>
  );
}

function Picker({ data, up, onPick, onClose, title = "Добавить упражнение" }) {
  return (
    <div className="fixed inset-0 z-50 overflow-y-auto bg-black" style={{ paddingTop: "env(safe-area-inset-top)" }}>
      <div className="mx-auto max-w-md p-4 pb-24">
        <Header title={title} right={<button onClick={onClose} className="p-2 text-neutral-400"><X size={22} /></button>} />
        <ExerciseList data={data} up={up} onSelect={onPick} autoFocus />
      </div>
    </div>
  );
}


// ---------- drag to reorder (hold the grip and pull) ----------
function moveItem(xs, from, to) { const [x] = xs.splice(from, 1); xs.splice(to, 0, x); }

// iOS WebKit can start a page scroll on a drag handle and then cancel our pointer stream.
// Block scrolling from handles (and everywhere while a drag is active) with non-passive listeners.
let dragActive = false;
if (typeof document !== "undefined" && !window.__dragGuard) {
  window.__dragGuard = true;
  document.addEventListener("touchstart", (e) => {
    if (e.target && e.target.closest && e.target.closest("[data-drag-handle]")) e.preventDefault();
  }, { passive: false });
  document.addEventListener("touchmove", (e) => { if (dragActive) e.preventDefault(); }, { passive: false });
}

function useSortable(onMove) {
  const [drag, setDrag] = useState(null); // {from, to, dy}
  const refs = useRef([]);
  const st = useRef(null);
  const raf = useRef(0);
  const onMoveRef = useRef(onMove);
  onMoveRef.current = onMove;

  const update = () => {
    const s = st.current;
    if (!s || !s.rects) return;
    const finger = s.y + window.scrollY;
    const r = s.rects[s.from];
    const dy = finger - (r.top + r.h / 2);
    let to = s.from;
    s.rects.forEach((q, j) => {
      const mid = q.top + q.h / 2;
      if (j > s.from && finger > mid) to = Math.max(to, j);
      if (j < s.from && finger < mid) to = Math.min(to, j);
    });
    if (dy !== s.dy || to !== s.to) { s.dy = dy; s.to = to; setDrag({ from: s.from, to, dy }); }
  };

  // measure after the list has re-rendered in compact drag mode
  useLayoutEffect(() => {
    const s = st.current;
    if (!drag || !s || s.rects) return;
    s.rects = refs.current.slice(0, s.count).map((el) => {
      const r = el.getBoundingClientRect();
      return { top: r.top + window.scrollY, h: r.height };
    });
    s.gap = s.rects.length > 1 ? s.rects[1].top - (s.rects[0].top + s.rects[0].h) : 8;
    update();
    const loop = () => {
      const c = st.current;
      if (!c) return;
      if (c.y < 90) window.scrollBy(0, -10);
      else if (c.y > window.innerHeight - 150) window.scrollBy(0, 10);
      update();
      raf.current = requestAnimationFrame(loop);
    };
    raf.current = requestAnimationFrame(loop);
  }, [drag]);

  useEffect(() => () => cancelAnimationFrame(raf.current), []);

  const winHandlers = useRef(null);
  const end = () => {
    cancelAnimationFrame(raf.current);
    dragActive = false;
    if (winHandlers.current) {
      window.removeEventListener("pointermove", winHandlers.current.move);
      window.removeEventListener("pointerup", winHandlers.current.up);
      window.removeEventListener("pointercancel", winHandlers.current.up);
      winHandlers.current = null;
    }
    const s = st.current;
    st.current = null;
    setDrag(null);
    if (s && s.to !== s.from) onMoveRef.current(s.from, s.to);
  };

  const handleProps = (i, count) => ({
    "data-drag-handle": "",
    style: { touchAction: "none", WebkitUserSelect: "none", userSelect: "none", WebkitTouchCallout: "none" },
    onPointerDown: (ev) => {
      ev.preventDefault();
      try { ev.currentTarget.setPointerCapture(ev.pointerId); } catch (e) {}
      st.current = { from: i, to: i, y: ev.clientY, count, rects: null, dy: 0 };
      dragActive = true;
      // listen on window too, in case pointer capture doesn't hold on this browser
      const move = (e2) => { if (st.current) { st.current.y = e2.clientY; update(); } };
      const upH = () => end();
      winHandlers.current = { move, up: upH };
      window.addEventListener("pointermove", move);
      window.addEventListener("pointerup", upH);
      window.addEventListener("pointercancel", upH);
      setDrag({ from: i, to: i, dy: 0 });
      try { navigator.vibrate && navigator.vibrate(15); } catch (e) {}
    },
  });

  const itemStyle = (i) => {
    const s = st.current;
    if (!drag || !s || !s.rects) return undefined;
    const h = s.rects[drag.from].h + s.gap;
    if (i === drag.from)
      return { transform: `translateY(${drag.dy}px)`, position: "relative", zIndex: 30, boxShadow: "0 12px 32px rgba(0,0,0,0.8)" };
    if (drag.from < drag.to && i > drag.from && i <= drag.to) return { transform: `translateY(${-h}px)`, transition: "transform 150ms" };
    if (drag.from > drag.to && i < drag.from && i >= drag.to) return { transform: `translateY(${h}px)`, transition: "transform 150ms" };
    return { transition: "transform 150ms" };
  };

  return { refs, handleProps, itemStyle, dragging: !!drag, dragFrom: drag ? drag.from : -1 };
}

// ---------- workout ----------
function startWorkout(up, p) {
  up((d) => {
    d.active = {
      id: uid(),
      programId: p?.id || null,
      name: p?.name || "Свободная тренировка",
      startedAt: Date.now(),
      segments: [{ start: Date.now() }],
      paused: false,
      restEndsAt: null,
      exercises: (p?.items || []).map((it) => ({ exerciseId: it.exerciseId, sets: buildSets(d, it.exerciseId, it.sets) })),
    };
  });
}

function WorkoutTab({ data, up, exMap, open }) {
  const a = data.active;
  const [picker, setPicker] = useState(false);
  const [askUpdate, setAskUpdate] = useState(false);
  const [sel, setSel] = useState(null); // {ei, set: Set<si>} while selecting sets to merge
  const cols = setColumns(data.settings);
  // hold a column title (кг, повт., …) and slide it left/right to reorder columns for all exercises
  const [colDrag, setColDrag] = useState(null); // {ei, key, dx, to}
  const hdrRefs = useRef({});
  const colPress = useRef(null);
  const reorderCols = (from, to) => up((d) => {
    const full = columnConfig(d.settings);
    const vis = setColumns(d.settings);
    const nv = vis.slice();
    const [k] = nv.splice(from, 1);
    nv.splice(to, 0, k);
    const visSet = new Set(vis);
    let j = 0;
    d.settings.columns = full.map((c) => {
      if (!visSet.has(c.key)) return c;
      const k2 = nv[j++];
      return full.find((x) => x.key === k2);
    });
  });
  const colHeaderProps = (ei, key) => ({
    ref: (el) => { hdrRefs.current[`${ei}:${key}`] = el; },
    style: {
      touchAction: "none", WebkitUserSelect: "none", userSelect: "none", WebkitTouchCallout: "none",
      ...(colDrag && colDrag.ei === ei && colDrag.key === key ? { transform: `translateX(${colDrag.dx}px)`, position: "relative", zIndex: 20 } : {}),
    },
    onContextMenu: (e) => e.preventDefault(),
    onPointerDown: (ev) => {
      const x0 = ev.clientX;
      const target = ev.currentTarget;
      clearTimeout(colPress.current);
      const cancel = () => clearTimeout(colPress.current);
      target.addEventListener("pointerup", cancel, { once: true });
      target.addEventListener("pointercancel", cancel, { once: true });
      colPress.current = setTimeout(() => {
        const rects = cols.map((c) => { const r = hdrRefs.current[`${ei}:${c}`].getBoundingClientRect(); return r.left + r.width / 2; });
        const from = cols.indexOf(key);
        let cur = { ei, key, dx: 0, to: from };
        setColDrag(cur);
        dragActive = true;
        try { navigator.vibrate && navigator.vibrate(20); } catch (e) {}
        const move = (e2) => {
          const dx = e2.clientX - x0;
          const x = rects[from] + dx;
          let to = 0, best = Infinity;
          rects.forEach((cx, j) => { if (Math.abs(x - cx) < best) { best = Math.abs(x - cx); to = j; } });
          cur = { ...cur, dx, to };
          setColDrag(cur);
        };
        const upH = () => {
          window.removeEventListener("pointermove", move);
          window.removeEventListener("pointerup", upH);
          window.removeEventListener("pointercancel", upH);
          dragActive = false;
          setColDrag(null);
          if (cur.to !== from) reorderCols(from, cur.to);
        };
        window.addEventListener("pointermove", move);
        window.addEventListener("pointerup", upH);
        window.addEventListener("pointercancel", upH);
      }, 250);
    },
  });
  const pressT = useRef(null);
  const longFired = useRef(false);
  const focusVal = useRef(null);
  const now = useNow(1000, !!a && !a.paused);
  const sort = useSortable((from, to) => up((d) => { moveItem(d.active.exercises, from, to); }));

  if (!a) {
    const last = data.workouts[data.workouts.length - 1];
    return (
      <div className="p-4">
        <Header title="Тренировка" />
        {last && <p className="text-xs text-neutral-400 mb-3">Прошлая: {last.name}, {fmtDate(last.startedAt)}</p>}
        {data.pendingProgramUpdate && data.programs.some((x) => x.id === data.pendingProgramUpdate.programId) && (
          <div className="mb-3 rounded-xl bg-neutral-900 p-4">
            <div className="font-semibold">Вчерашняя тренировка завершена</div>
            <p className="mb-3 text-xs text-neutral-400">
              Она отличалась от «{data.programs.find((x) => x.id === data.pendingProgramUpdate.programId).name}». Записать изменения в программу?
            </p>
            <div className="flex gap-2">
              <button onClick={() => up((d) => { delete d.pendingProgramUpdate; })} className="rounded-xl bg-neutral-800 px-4 py-2.5 text-neutral-300">Нет</button>
              <button onClick={() => up((d) => {
                const pu = d.pendingProgramUpdate;
                const pp = pu && d.programs.find((x) => x.id === pu.programId);
                if (pp) pp.items = pu.items;
                delete d.pendingProgramUpdate;
              })} className="flex-1 rounded-xl bg-amber-400 py-2.5 font-semibold text-black">Обновить программу</button>
            </div>
          </div>
        )}
        <div className="space-y-2">
          {data.programs.map((p) => (
            <div key={p.id} className="flex items-stretch gap-2 rounded-xl bg-neutral-900 p-2 pl-4">
              <button onClick={() => open({ type: "program", id: p.id })} className="min-w-0 flex-1 py-2 text-left">
                <div className="text-base font-semibold">{p.name}</div>
                <div className="mt-1 text-xs text-neutral-400">
                  {p.items.map((i) => exMap[i.exerciseId]?.name).filter(Boolean).join(", ") || "Пока без упражнений"}
                </div>
              </button>
              <button onClick={() => startWorkout(up, p)} aria-label="Начать"
                className="flex w-14 shrink-0 items-center justify-center rounded-lg bg-amber-400 text-black">
                <Play size={22} />
              </button>
            </div>
          ))}
          <div className="flex gap-2">
            <button onClick={() => {
              const id = uid();
              up((d) => { d.programs.push({ id, name: "Новая программа", items: [] }); });
              open({ type: "program", id });
            }} className="flex-1 rounded-xl border border-dashed border-neutral-700 p-4 text-neutral-300">
              + Новая программа
            </button>
            <button onClick={() => startWorkout(up, null)} className="flex-1 rounded-xl border border-dashed border-neutral-700 p-4 text-neutral-300">
              Без программы
            </button>
          </div>
        </div>
      </div>
    );
  }

  const st = stats(a, exMap);
  const setSet = (ei, si, patch) => up((d) => { Object.assign(d.active.exercises[ei].sets[si], patch); });
  const toggle = (ei, si) => {
    unlockAudio();
    up((d) => {
      const s = d.active.exercises[ei].sets[si];
      s.done = !s.done;
      if (s.done) {
        // confirming a set without typing means "same as last time"
        if (s.w === "" && s.hw) s.w = s.hw;
        if (s.r === "" && s.hr) s.r = s.hr;
        if (!s.p && s.hp) s.p = s.hp;
        if (num(s.p) > 0 && s.t !== "w") s.rir = 0; // partials mean the set went to failure
      }
      if (s.done && d.active.paused) { closeSegment(d.active); d.active.segments.push({ start: Date.now() }); d.active.paused = false; }
      if (s.done) {
        s.at = Date.now(); // for rest-time stats
        d.active.lastSetAt = s.at;
        // no rest in the middle of a drop set / ladder
        const nx = d.active.exercises[ei].sets[si + 1];
        const midGroup = s.g && nx && nx.g === s.g && !nx.done;
        const countdown = d.settings.restMode !== "stopwatch";
        d.active.restEndsAt = midGroup || !countdown ? null : Date.now() + d.settings.restSec * 1000;
      } else {
        delete s.at;
      }
    });
  };
  const addSet = (ei) => up((d) => {
    const ss = d.active.exercises[ei].sets, l = ss[ss.length - 1];
    ss.push({ w: "", r: "", p: "", hw: l ? l.w || l.hw || "" : "", hr: l ? l.r || l.hr || "" : "", hp: l ? l.p || l.hp || "" : "", done: false });
  });
  const delSet = (ei, si) => { setSel(null); up((d) => { const ss = d.active.exercises[ei].sets; ss.splice(si, 1); normalizeGroups(ss); }); };
  const mergeSel = () => {
    const { ei, set } = sel;
    const idx = [...set].sort((x, y) => x - y);
    up((d) => {
      const ex0 = d.active.exercises[ei];
      const ss = ex0.sets;
      const g = uid();
      const picked = idx.map((i) => ss[i]);
      picked.forEach((st) => { st.g = g; });
      const rest = ss.filter((_, i) => !set.has(i));
      const at = ss.slice(0, idx[0]).filter((_, i) => !set.has(i)).length;
      rest.splice(at, 0, ...picked);
      normalizeGroups(rest);
      ex0.sets = rest;
    });
    setSel(null);
  };
  const unmergeSel = () => {
    const { ei, set } = sel;
    up((d) => { const ss = d.active.exercises[ei].sets; set.forEach((i) => { if (ss[i]) delete ss[i].g; }); normalizeGroups(ss); });
    setSel(null);
  };
  // number cell: tap = warm-up on/off (or select while selecting), long press = start selecting
  const pressProps = (ei, si) => ({
    onPointerDown: () => {
      longFired.current = false;
      clearTimeout(pressT.current);
      pressT.current = setTimeout(() => {
        longFired.current = true;
        try { navigator.vibrate && navigator.vibrate(20); } catch (e) {}
        setSel({ ei, set: new Set([si]) });
      }, 450);
    },
    onPointerUp: () => clearTimeout(pressT.current),
    onPointerLeave: () => clearTimeout(pressT.current),
    onPointerCancel: () => clearTimeout(pressT.current),
    onContextMenu: (ev) => ev.preventDefault(),
    onClick: () => {
      if (longFired.current) { longFired.current = false; return; }
      if (sel && sel.ei === ei) {
        setSel((prev) => { const n = new Set(prev.set); if (n.has(si)) n.delete(si); else n.add(si); return n.size ? { ei, set: n } : null; });
      } else {
        const cur = a.exercises[ei].sets[si];
        setSet(ei, si, cur.t === "w" ? { t: "" } : { t: "w", rir: null });
      }
    },
  });
  // merge the next set into this one as extra steps (one set, no rest in between)
  const mergeNext = (ei, si) => up((d) => {
    const ss = d.active.exercises[ei].sets, s = ss[si], n = ss[si + 1];
    if (!n) return;
    if (!s.drops) s.drops = [];
    s.drops.push({ w: n.w, r: n.r, hw: n.hw || "", hr: n.hr || "" }, ...(n.drops || []));
    s.done = s.done || n.done;
    ss.splice(si + 1, 1);
  });
  const splitSet = (ei, si) => up((d) => {
    const ss = d.active.exercises[ei].sets, s = ss[si];
    const parts = (s.drops || []).map((dr) => ({ w: dr.w, r: dr.r, p: "", hw: dr.hw || "", hr: dr.hr || "", hp: "", done: s.done }));
    s.drops = [];
    ss.splice(si + 1, 0, ...parts);
  });
  // typing reps means the set was done: confirm it, or restart rest if it was already confirmed
  const commitOnBlur = (ei, si, field) => {
    const s = a.exercises[ei]?.sets[si];
    if (!s || (s[field] || "") === (focusVal.current || "")) return;
    if (!s.done) { if ((s[field] || "") !== "") toggle(ei, si); }
    else up((d) => { d.active.restEndsAt = Date.now() + d.settings.restSec * 1000; });
  };
  const delEx = (ei) => up((d) => { d.active.exercises.splice(ei, 1); });
  const moveEx = (ei, dir) => up((d) => {
    const xs = d.active.exercises, j = ei + dir;
    if (j < 0 || j >= xs.length) return;
    [xs[ei], xs[j]] = [xs[j], xs[ei]];
  });
  const addEx = (ex) => {
    const rep = picker.replace;
    up((d) => {
      if (rep !== undefined) {
        const e = d.active.exercises[rep];
        if (e) { e.exerciseId = ex.id; e.sets = buildSets(d, ex.id, e.sets.length || 3); }
      } else d.active.exercises.push({ exerciseId: ex.id, sets: buildSets(d, ex.id, 3) });
    });
    setPicker(false);
  };
  const hasDone = a.exercises.some((e) => e.sets.some((s) => s.done));
  const program = a.programId ? data.programs.find((p) => p.id === a.programId) : null;
  const newItems = a.exercises.map((e) => ({ exerciseId: e.exerciseId, sets: e.sets.length || 1 }));
  const programChanged = !!program && JSON.stringify(program.items) !== JSON.stringify(newItems);
  const finish = () => (programChanged ? setAskUpdate(true) : doFinish(false));
  const doFinish = (updateProgram) => {
    setAskUpdate(false);
    const id = a.id;
    up((d) => { finalizeActive(d, updateProgram); });
    if (hasDone) open({ type: "workout", id });
  };
  const pause = () => up((d) => { closeSegment(d.active); d.active.paused = true; d.active.restEndsAt = null; });
  const resume = () => up((d) => { closeSegment(d.active); d.active.segments.push({ start: Date.now() }); d.active.paused = false; });
  const segs = segmentsOf(a);
  const cur = segs[segs.length - 1];
  const dur = durations(a, now);

  return (
    <div className="p-4 pb-44">
      <div className="mb-4 flex items-start justify-between gap-3">
        <div>
          <p className="text-xs text-neutral-400">{a.paused ? "На паузе" : segs.length > 1 ? `Продолжение, отрезок ${segs.length}` : "Идёт тренировка"}</p>
          <h1 className="text-lg font-bold">{a.name}</h1>
        </div>
        <div className="text-right">
          <div className={`text-2xl font-bold tabular-nums ${a.paused ? "text-neutral-500" : "text-amber-400"}`}>
            {a.paused ? fmtDur(dur.main) : fmtDur(now - cur.start)}
          </div>
          <div className="text-xs text-neutral-400 tabular-nums">
            {st.sets} подх., {fmtKg(st.vol)}
            {segs.length > 1 && <span className="block">основная {fmtDur(dur.main)}{dur.extra >= 60000 ? `, +${fmtDur(dur.extra)}` : ""}</span>}
          </div>
        </div>
      </div>

      {a.paused && (
        <button onClick={resume} className="mb-3 flex w-full items-center justify-center gap-2 rounded-xl bg-amber-400 py-3 font-semibold text-black">
          <Play size={18} /> Продолжить тренировку
        </button>
      )}

      {a.exercises.map((e, ei) => {
        const ex = exMap[e.exerciseId] || { name: "Удалённое упражнение", kind: "reps" };
        const last = lastSession(data.workouts, e.exerciseId);
        return (
          <div key={ei + e.exerciseId} ref={(el) => { sort.refs.current[ei] = el; }} style={sort.itemStyle(ei)}
            className={`mb-3 rounded-xl p-3 ${sort.dragFrom === ei ? "bg-neutral-800" : "bg-neutral-900"}`}>
            <div className={`flex items-center gap-1 ${sort.dragging ? "" : "mb-2"}`}>
              <button {...sort.handleProps(ei, a.exercises.length)} className="-ml-1 cursor-grab p-1 text-neutral-500" aria-label="Перетащить">
                <GripVertical size={20} />
              </button>
              <ExImg ex={exMap[e.exerciseId]} />
              <button onClick={() => open({ type: "exercise", id: e.exerciseId })} className="ml-2 min-w-0 flex-1 text-left">
                <div className="font-semibold">{ex.name}</div>
                {ex.ru && <div className="truncate text-xs text-neutral-500">{ex.ru}</div>}
                {last && !sort.dragging && <div className="truncate text-xs text-neutral-400">Прошлый раз: {fmtSets(last.sets, ex.kind)}</div>}
              </button>
              <button onClick={() => setPicker({ replace: ei })} className="p-1.5 text-neutral-500" aria-label="Заменить"><RefreshCw size={18} /></button>
              <ConfirmButton onConfirm={() => delEx(ei)} className="p-1.5 text-neutral-500" armedClassName="rounded-md bg-red-600 px-2 py-1 text-xs text-white">
                <Trash2 size={18} />
              </ConfirmButton>
            </div>
            {!sort.dragging && (<>
            <div className="flex items-center gap-1.5 px-1 text-[11px] text-neutral-500">
              <span className="w-8" />
              {cols.map((c) => (
                <span key={c} {...colHeaderProps(ei, c)}
                  className={`${c === "w" || c === "r" ? "flex-1" : "w-10"} rounded py-1 text-center ${
                    colDrag && colDrag.ei === ei ? (colDrag.key === c ? "bg-amber-400 text-black" : cols[colDrag.to] === c ? "bg-neutral-700 text-neutral-200" : "") : ""}`}>
                  {c === "w" ? (ex.assist ? "помощь" : ex.bw ? "+кг" : "кг") : c === "r" ? (ex.kind === "time" ? "сек" : "повт.") : c === "p" ? (ex.kind === "time" ? "" : "частич.") : "RIR"}
                </span>
              ))}
              <span className="w-10" /><span className="w-5" />
            </div>
            {(() => {
              const labels = setLabels(e.sets);
              return e.sets.map((s, si) => {
                const inSel = sel && sel.ei === ei && sel.set.has(si);
                const cont = s.g && si > 0 && e.sets[si - 1].g === s.g;
                const box = "rounded-lg bg-black px-1 py-2.5 text-center text-base tabular-nums outline-none placeholder-neutral-600 focus:ring-2 focus:ring-amber-400";
                const rirShown = s.rir == null ? "" : s.rir === 4 ? "4+" : String(s.rir);
                const cell = (c) => {
                  if (c === "w") return (
                    <input key={c} value={s.w} placeholder={s.hw || ""} inputMode="decimal" onChange={(ev) => setSet(ei, si, { w: ev.target.value })}
                      className={`min-w-0 flex-1 ${box} ${s.done ? "text-amber-300" : ""}`} />
                  );
                  if (c === "r") return (
                    <input key={c} value={s.r} placeholder={s.hr || ""} inputMode="numeric" onChange={(ev) => setSet(ei, si, { r: ev.target.value })}
                      className={`min-w-0 flex-1 ${box} ${s.done ? "text-amber-300" : ""}`} />
                  );
                  if (c === "p") return ex.kind === "time" ? <span key={c} className="w-10" /> : (
                    <input key={c} value={s.p || ""} inputMode="numeric" placeholder={s.hp ? String(s.hp) : "+"} aria-label="Частичные повторы"
                      onChange={(ev) => setSet(ei, si, { p: ev.target.value, ...(num(ev.target.value) > 0 && s.t !== "w" ? { rir: 0 } : {}) })}
                      className={`w-10 ${box} ${s.done ? "text-amber-300" : "text-neutral-300"}`} />
                  );
                  return (
                    <input key={c} value={rirShown} inputMode="numeric" placeholder="–" aria-label="RIR, повторов в запасе" disabled={s.t === "w"}
                      onChange={(ev) => {
                        const raw = ev.target.value;
                        if (raw.length < rirShown.length) return setSet(ei, si, { rir: null });
                        const dg = raw.replace(/\D/g, "").slice(-1);
                        setSet(ei, si, { rir: dg === "" ? null : Math.min(4, parseInt(dg, 10)) });
                      }}
                      className={`w-10 ${box} disabled:opacity-30 ${s.rir === 0 ? "text-red-400" : s.done ? "text-amber-300" : "text-neutral-300"}`} />
                  );
                };
                return (
                  <div key={si}
                    className={`flex items-center gap-1.5 rounded-lg px-1 ${cont ? "mt-0.5" : "mt-1.5"} ${s.g ? "border-l-2 border-amber-400" : "border-l-2 border-transparent"} ${inSel ? "bg-neutral-700" : ""}`}>
                    <button {...pressProps(ei, si)} aria-label="Подход: тап — разминка, удержание — выбрать"
                      style={{ WebkitTouchCallout: "none", WebkitUserSelect: "none", userSelect: "none" }}
                      className={`flex h-11 w-8 shrink-0 items-center justify-center rounded-lg text-sm font-semibold ${inSel ? "bg-amber-400 text-black" : "bg-black"}`}>
                      <span className={inSel ? "" : s.t === "w" ? "text-sky-400" : s.done ? "text-amber-400" : "text-neutral-500"}>{s.t === "w" ? "Р" : labels[si]}</span>
                    </button>
                    {cols.map(cell)}
                    <button onClick={() => toggle(ei, si)} aria-label="Подход сделан"
                      className={`flex h-11 w-10 shrink-0 items-center justify-center rounded-lg ${s.done ? "bg-amber-400 text-neutral-900" : "bg-neutral-800 text-neutral-400"}`}>
                      <Check size={20} />
                    </button>
                    <button onClick={() => delSet(ei, si)} className="w-5 shrink-0 text-neutral-600" aria-label="Удалить подход"><X size={16} /></button>
                  </div>
                );
              });
            })()}
            {sel && sel.ei === ei ? (
              <div className="mt-2 flex items-center gap-1.5 rounded-lg bg-neutral-800 p-2 text-xs">
                <span className="flex-1 text-neutral-300">Выбрано: {sel.set.size}</span>
                <button disabled={sel.set.size < 2} onClick={mergeSel} className="rounded-md bg-amber-400 px-3 py-2 font-semibold text-black disabled:opacity-40">Объединить</button>
                <button onClick={unmergeSel} className="rounded-md bg-neutral-700 px-3 py-2">Разъединить</button>
                <button onClick={() => setSel(null)} className="px-2 py-2 text-neutral-400">Отмена</button>
              </div>
            ) : (
              <button onClick={() => addSet(ei)} className="mt-2 w-full rounded-lg py-2 text-xs text-neutral-400 active:bg-neutral-800">
                Добавить подход
              </button>
            )}
            </>)}
          </div>
        );
      })}

      <button onClick={() => setPicker(true)} className="w-full rounded-xl border border-dashed border-neutral-700 py-3 text-neutral-300">
        Добавить упражнение
      </button>

      <div className="mt-6 flex gap-2">
        <ConfirmButton onConfirm={() => up((d) => { d.active = null; })} confirmText="Удалить тренировку?"
          className="rounded-xl bg-neutral-900 px-4 py-3 text-neutral-400" armedClassName="rounded-xl bg-red-600 px-4 py-3 text-white">
          Отменить
        </ConfirmButton>
        {a.paused ? (
          <>
            <button onClick={resume} className="flex-1 rounded-xl bg-amber-400 py-3 font-semibold text-black">Продолжить</button>
            <button onClick={finish} className="rounded-xl bg-neutral-800 px-4 py-3">Завершить</button>
          </>
        ) : (
          <>
            <button onClick={pause} className="rounded-xl bg-neutral-800 px-4 py-3">Пауза</button>
            <button onClick={finish} className="flex-1 rounded-xl bg-amber-400 py-3 font-semibold text-black">Завершить</button>
          </>
        )}
      </div>

      {askUpdate && (
        <div className="fixed inset-0 z-50 flex items-end bg-black/70 p-3" onClick={() => setAskUpdate(false)}>
          <div className="safe-bottom mx-auto w-full max-w-md rounded-2xl bg-neutral-900 p-4" onClick={(e) => e.stopPropagation()}>
            <div className="mb-1 text-base font-semibold">Обновить программу?</div>
            <p className="mb-4 text-xs text-neutral-400">
              Состав или подходы отличаются от «{program?.name}». Можно записать в программу то, как ты тренировался сегодня.
            </p>
            <button onClick={() => doFinish(true)} className="mb-2 w-full rounded-xl bg-amber-400 py-3 font-semibold text-black">Обновить программу</button>
            <button onClick={() => doFinish(false)} className="w-full rounded-xl bg-neutral-800 py-3 text-neutral-300">Оставить программу как была</button>
          </div>
        </div>
      )}

      {picker && <Picker data={data} up={up} onPick={addEx} onClose={() => setPicker(false)}
        title={picker.replace !== undefined ? "Заменить упражнение" : undefined} />}
    </div>
  );
}

function SinceBar({ since }) {
  const now = useNow(1000, true);
  return (
    <div className="above-nav pointer-events-none fixed inset-x-0 z-40 flex justify-center px-3">
      <div className="rounded-full bg-neutral-100 px-4 py-2 text-sm font-semibold tabular-nums text-black shadow-lg">
        Отдых {fmtDur(now - since)}
      </div>
    </div>
  );
}

function RestBar({ endsAt, total, up, sound }) {
  const now = useNow(200, true);
  const left = endsAt - now;
  const done = left <= 0;
  const fired = useRef(null);
  const ticked = useRef(new Set());
  useEffect(() => { if (sound && endsAt - Date.now() > total * 1000 - 1500) blip(); }, []);
  const secLeft = Math.ceil(left / 1000);
  useEffect(() => {
    if (!sound || done || secLeft > 3 || ticked.current.has(secLeft)) return;
    ticked.current.add(secLeft);
    tick();
  }, [secLeft, done]);
  useEffect(() => {
    if (!done) return;
    if (fired.current !== endsAt) {
      fired.current = endsAt;
      if (Date.now() - endsAt < 5000) {
        if (sound) beep();
        try { navigator.vibrate && navigator.vibrate([300, 150, 300]); } catch (e) {}
      }
    }
    const t = setTimeout(() => up((d) => { if (d.active) d.active.restEndsAt = null; }), 2500);
    return () => clearTimeout(t);
  }, [done, endsAt]);
  const adjust = (sec) => up((d) => { if (d.active?.restEndsAt) d.active.restEndsAt += sec * 1000; });
  const pct = Math.min(100, Math.max(0, (left / (total * 1000)) * 100));

  return (
    <div className="above-nav fixed inset-x-0 z-40 px-3">
      <div className={`mx-auto max-w-md overflow-hidden rounded-2xl shadow-lg ${done ? "bg-amber-400 text-neutral-900" : "bg-neutral-100 text-neutral-900"}`}>
        <div className="h-1.5 bg-neutral-300"><div className="h-full bg-amber-500" style={{ width: `${pct}%`, transition: "width 250ms linear" }} /></div>
        <div className="flex items-center gap-2 p-3">
          <div className="flex-1">
            <div className="text-xs text-neutral-600">{done ? "Время подхода" : "Отдых"}</div>
            <div className="text-2xl font-bold tabular-nums">{done ? "0:00" : fmtDur(left + 999)}</div>
          </div>
          <button onClick={() => adjust(-15)} className="rounded-lg bg-neutral-300 px-3 py-2 font-semibold tabular-nums">−15</button>
          <button onClick={() => adjust(15)} className="rounded-lg bg-neutral-300 px-3 py-2 font-semibold tabular-nums">+15</button>
          <button onClick={() => up((d) => { if (d.active) d.active.restEndsAt = null; })} className="rounded-lg bg-black px-3 py-2 font-semibold text-neutral-100">
            Хватит
          </button>
        </div>
      </div>
    </div>
  );
}

